      { name: '常用说法', rule: '前面常加 한번“一下”。보세요 是礼貌地请对方试，볼게요 是“我来试试”。', rows: [['해 봐', '한번 해 보세요.', '请试一下'], ['해 봐', '제가 해 볼게요.', '我来试试'], ['가 봐', '한번 가 볼까?', '去看看吧？']] }
