      { name: '有收音：은 적 있어', rule: '듣다 的 ㄷ 要变成 ㄹ：들은 적。', rows: [['먹다', '먹은 적 있어.', '吃过'], ['읽다', '읽은 적 없어.', '没读过'], ['듣다', '들은 적 없어.', '没听过']] },
      { name: '아/어 본 적：试过', rule: '前面先加 아/어 보다，说“亲身经历过”，口语里最常用。', rows: [['가 보다', '가 본 적 있어?', '去过吗？'], ['먹어 보다', '먹어 본 적 있어?', '吃过吗？'], ['나와 보다', '방송에 나와 본 적 있어요?', '上过节目吗？']] }
