      { name: '句尾：려고요、려고 했어', rule: '려고요 回答“为什么”；려고 했어 是“本来想…”，多半没做成。', rows: [['사귀려고', '친구를 사귀려고요.', '是想交朋友'], ['전화하려고', '전화하려고 했어.', '本来想给你打电话'], ['하려고', '뭐 하려고?', '你想干嘛？']] }
