      { name: '已经发生：았는데 / 었는데', rule: '过去时 았、었、했 后面一律加 는데，不管前面是动作还是形容词。', rows: [['먹었다', '먹었는데', '吃过了…'], ['왔다', '왔는데', '来了…'], ['바빴다', '바빴는데', '（之前）很忙…']] }
