      { name: '底下本来是 ㄹ：直接 텐데', rule: '去掉 다 后底下已经是 ㄹ（멀、힘들），不用再加。', rows: [['멀다', '거기 멀 텐데.', '那儿应该挺远吧'], ['힘들다', '힘들 텐데 괜찮아?', '应该很辛苦吧，还好吗？']] },
      { name: '已经发生：았/었을 텐데', rule: '猜过去的事，先变过去时（底下有 ㅆ），再补 을 텐데；遗憾说 았/었으면 좋았을 텐데。', rows: [['나가다', '싸우는 장면만 나갔을 텐데…', '播出去的应该全是吵架的镜头吧……'], ['도착하다', '벌써 도착했을 텐데.', '应该已经到了吧'], ['같이 가다', '같이 갔으면 좋았을 텐데.', '要是一起去就好了']] }
